global.schema:
type VetraAppState {
  name: String
  slug: String
  owner: EthereumAddress
  status: VetraAppStatus!
  repository: VetraAppRepository
  identity: VetraAppIdentity
  productionEnvironmentId: OID
  previews: VetraAppPreviews
  artifacts: [VetraAppArtifact!]!
}

enum VetraAppStatus {
  PENDING_IDENTITY
  ACTIVE
  DISCONNECTED
  DELETED
}

type VetraAppRepository {
  repositoryId: String
  fullName: String
  productionBranch: String
}

type VetraAppIdentity {
  did: String
  expiresAt: DateTime
}

type VetraAppPreviews {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

type VetraAppArtifact {
  id: OID!
  kind: VetraAppArtifactKind!
  name: String!
  versions: [VetraAppArtifactVersion!]!
  channels: [VetraAppArtifactChannel!]!
}

enum VetraAppArtifactKind {
  PACKAGE
  FUSION_IMAGE
}

type VetraAppArtifactVersion {
  version: String!
  reference: String!
  commitSha: String
  runId: String
  publishedAt: DateTime!
}

type VetraAppArtifactChannel {
  channel: AutoUpdateChannel!
  version: String!
}

enum AutoUpdateChannel {
  DEV
  STAGING
  LATEST
}

operations.schema:
input SetAppDetailsInput {
  name: String
  slug: String
  owner: EthereumAddress
}

operations.reducer:
if (action.input.name) state.name = action.input.name;
if (action.input.slug) state.slug = action.input.slug;
if (action.input.owner) state.owner = action.input.owner;

operations.schema:
input ConnectRepositoryInput {
  repositoryId: String
  fullName: String
  productionBranch: String
}

operations.reducer:
state.repository = {
  repositoryId: action.input.repositoryId ?? null,
  fullName: action.input.fullName ?? null,
  productionBranch: action.input.productionBranch ?? null,
};

operations.schema:
input SetIdentityInput {
  did: String
  expiresAt: DateTime
}

operations.reducer:
state.identity = {
  did: action.input.did ?? null,
  expiresAt: action.input.expiresAt ?? null,
};

operations.schema:
input SetPreviewsInput {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

operations.reducer:
state.previews = {
  enabled: action.input.enabled,
  limit: action.input.limit,
  ttlDays: action.input.ttlDays,
};

const MAX_ARTIFACT_VERSIONS = 50;

let artifact = state.artifacts.find(
  (a) => a.kind === action.input.kind && a.name === action.input.name,
);
if (!artifact) {
  artifact = {
    id: `${action.input.kind}:${action.input.name}`,
    kind: action.input.kind,
    name: action.input.name,
    versions: [],
    channels: [],
  };
  state.artifacts.push(artifact);
}

const entry = {
  version: action.input.version,
  reference: action.input.reference,
  commitSha: action.input.commitSha ?? null,
  runId: action.input.runId ?? null,
  publishedAt: action.input.publishedAt,
};
const at = artifact.versions.findIndex((v) => v.version === action.input.version);
if (at >= 0) {
  artifact.versions[at] = entry;
} else {
  artifact.versions.push(entry);
}

// A document that grows without bound eventually fails to load, and a dropdown
// never needs the whole history.
if (artifact.versions.length > MAX_ARTIFACT_VERSIONS) {
  artifact.versions = artifact.versions.slice(
    artifact.versions.length - MAX_ARTIFACT_VERSIONS,
  );
}
// A channel aimed at a version the cap dropped is worse than no channel.
artifact.channels = artifact.channels.filter((c) =>
  artifact.versions.some((v) => v.version === c.version),
);

operations.schema:
input SetArtifactChannelInput {
  kind: VetraAppArtifactKind!
  name: String!
  channel: AutoUpdateChannel!
  version: String!
}

operations.reducer:
const artifact = state.artifacts.find(
  (a) => a.kind === action.input.kind && a.name === action.input.name,
);
if (!artifact) {
  throw new UnknownArtifactError(
    `${action.input.kind} ${action.input.name} has published nothing`,
  );
}
if (!artifact.versions.some((v) => v.version === action.input.version)) {
  throw new UnknownArtifactVersionError(
    `${action.input.name} has no published version ${action.input.version}`,
  );
}
const at = artifact.channels.findIndex((c) => c.channel === action.input.channel);
const entry = { channel: action.input.channel, version: action.input.version };
if (at >= 0) {
  artifact.channels[at] = entry;
} else {
  artifact.channels.push(entry);
}
